import java.util.*;
import java.io.*;

public class Main {
    static boolean[] searchMatrix(int[][] matrix, int[] targets) {
        // Write your solution here
        return new boolean[targets.length];
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int r = (int) in.nval;
        in.nextToken();
        int c = (int) in.nval;
        int[][] matrix = new int[r][c];
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) {
                in.nextToken();
                matrix[i][j] = (int) in.nval;
            }
        }
        in.nextToken();
        int q = (int) in.nval;
        int[] targets = new int[q];
        for (int i = 0; i < q; i++) {
            in.nextToken();
            targets[i] = (int) in.nval;
        }
        boolean[] res = searchMatrix(matrix, targets);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < res.length; i++) sb.append(res[i] ? "true" : "false").append("\n");
        System.out.print(sb);
    }
}

